def get_active_contract(user_id):
    reset_daily_contracts_if_needed(user_id)

    cursor.execute("""
    SELECT
        id,
        user_id,
        created_date,
        player_level,
        target_mob_name,
        target_mob_level,
        target_min_level,
        target_max_level,
        target_kills,
        current_kills,
        reward_exp,
        completed,
        reward_claimed
    FROM user_active_contracts
    WHERE user_id=?
    ORDER BY id DESC
    LIMIT 1
    """, (user_id,))

    row = cursor.fetchone()

    if not row:
        return None

    (
        contract_id,
        row_user_id,
        created_date,
        player_level,
        target_mob_name,
        target_mob_level,
        target_min_level,
        target_max_level,
        target_kills,
        current_kills,
        reward_exp,
        completed,
        reward_claimed
    ) = row

    if not target_mob_name:
        return None

    return {
        "id": contract_id,
        "user_id": row_user_id,
        "created_date": created_date,
        "player_level": player_level,
        "target_mob_name": target_mob_name,
        "target_mob_level": target_mob_level,
        "target_min_level": target_min_level,
        "target_max_level": target_max_level,
        "target_kills": target_kills,
        "current_kills": current_kills,
        "reward_exp": reward_exp,
        "completed": bool(completed),
        "reward_claimed": bool(reward_claimed)
    }

def get_contract_status(user_id):
    reset_daily_contracts_if_needed(user_id)

    cursor.execute("""
    SELECT level, daily_contracts_completed
    FROM users
    WHERE user_id=?
    """, (user_id,))

    row = cursor.fetchone()

    if not row:
        return {
            "exists": False,
            "message": "❌ Персонажа не знайдено"
        }

    level, completed_today = row
    completed_today = completed_today or 0

    active_contract = get_active_contract(user_id)

    return {
        "exists": True,
        "level": level,
        "unlocked": level >= CONTRACTS_UNLOCK_LEVEL,
        "completed_today": completed_today,
        "daily_limit": DAILY_CONTRACT_LIMIT,
        "active_contract": active_contract
    }

def create_daily_contract(
    user_id,
    target_mob_name,
    target_mob_level,
    target_kills=CONTRACT_TARGET_KILLS
):
    reset_daily_contracts_if_needed(user_id)

    status = get_contract_status(user_id)

    if not status["exists"]:
        return {
            "success": False,
            "message": "❌ Персонажа не знайдено"
        }

    level = status["level"]

    if level < CONTRACTS_UNLOCK_LEVEL:
        return {
            "success": False,
            "message": (
                f"🔒 Контракти відкриються з {CONTRACTS_UNLOCK_LEVEL} рівня.\n"
                f"Твій рівень: {level}"
            )
        }

    if status["completed_today"] >= DAILY_CONTRACT_LIMIT:
        return {
            "success": False,
            "message": (
                f"📜 Ліміт контрактів на сьогодні виконано.\n"
                f"✅ Виконано: {status['completed_today']}/{DAILY_CONTRACT_LIMIT}"
            )
        }

    if status["active_contract"]:
        active = status["active_contract"]

        if active.get("completed"):
            return {
                "success": False,
                "message": (
                    "📜 У тебе вже є виконаний контракт.\n\n"
                    "Повернися до Гільдії Найманців і здай його, "
                    "щоб отримати нагороду."
                )
            }

        return {
            "success": False,
            "message": "📜 У тебе вже є активний контракт."
        }

    reward_exp = get_contract_exp_for_level(level)

    target_min_level = max(1, level - 1)
    target_max_level = level + 1

    cursor.execute("""
    INSERT INTO user_active_contracts (
        user_id,
        created_date,
        player_level,
        target_mob_name,
        target_mob_level,
        target_min_level,
        target_max_level,
        target_kills,
        current_kills,
        reward_exp,
        completed,
        reward_claimed
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        user_id,
        get_today_str(),
        level,
        target_mob_name,
        int(target_mob_level),
        target_min_level,
        target_max_level,
        int(target_kills),
        0,
        reward_exp,
        0,
        0
    ))

    conn.commit()

    return {
        "success": True,
        "message": (
            f"📜 Контракт прийнято!\n\n"
            f"🎯 Завдання:\n"
            f"Вбий {target_kills} × {target_mob_name} "
            f"(рівень {target_mob_level}).\n\n"
            f"✨ Нагорода після здачі: {reward_exp} EXP"
        )
    }

def abandon_active_contract(user_id):
    reset_daily_contracts_if_needed(user_id)

    active_contract = get_active_contract(user_id)

    if not active_contract:
        return {
            "success": False,
            "message": "📜 У тебе немає активного контракту."
        }

    cursor.execute("""
    DELETE FROM user_active_contracts
    WHERE user_id=?
    """, (user_id,))

    conn.commit()

    return {
        "success": True,
        "message": "📜 Активний контракт скасовано."
    }

def process_contract_progress_on_kill(user_id, mob):
    reset_daily_contracts_if_needed(user_id)

    active_contract = get_active_contract(user_id)

    if not active_contract:
        return {
            "updated": False,
            "completed": False,
            "message": None
        }

    if active_contract.get("reward_claimed"):
        return {
            "updated": False,
            "completed": False,
            "message": None
        }

    if active_contract.get("completed"):
        return {
            "updated": False,
            "completed": True,
            "message": None
        }

    mob_name = mob.get("name", "")
    mob_base_name = mob.get("base_name", mob_name)
    mob_level = int(mob.get("level", active_contract["target_mob_level"]))

    target_name = active_contract["target_mob_name"]
    target_level = int(active_contract["target_mob_level"])

    if mob_base_name != target_name or mob_level != target_level:
        return {
            "updated": False,
            "completed": False,
            "message": None
        }

    new_progress = active_contract["current_kills"] + 1

    if new_progress >= active_contract["target_kills"]:
        cursor.execute("""
        UPDATE user_active_contracts
        SET current_kills=?,
            completed=1
        WHERE id=?
        """, (
            active_contract["target_kills"],
            active_contract["id"]
        ))

        conn.commit()

        return {
            "updated": True,
            "completed": True,
            "message": (
                f"📜 Контракт виконано!\n"
                f"🎯 Ціль: {target_name}\n"
                f"✅ Прогрес: {active_contract['target_kills']}/{active_contract['target_kills']}\n"
                f"🏛️ Поверніться до Гільдії Найманців, щоб здати контракт і отримати нагороду."
            )
        }

    cursor.execute("""
    UPDATE user_active_contracts
    SET current_kills=?
    WHERE id=?
    """, (new_progress, active_contract["id"]))

    conn.commit()

    elite_note = ""

    if mob.get("is_elite"):
        elite_note = " ⭐ Елітна ціль зарахована!"

    return {
        "updated": True,
        "completed": False,
        "message": (
            f"📜 Контракт: {target_name} "
            f"{new_progress}/{active_contract['target_kills']}"
            f"{elite_note}"
        )
    }

def migrate_active_contracts_target_kills_to_5():
    init_contract_system()

    cursor.execute("""
    UPDATE user_active_contracts
    SET target_kills=5
    WHERE target_kills > 5
    """)

    cursor.execute("""
    UPDATE user_active_contracts
    SET completed=1,
        current_kills=5
    WHERE target_kills=5
      AND current_kills >= 5
      AND reward_claimed=0
    """)

    conn.commit()

    return True


def _claim_contract_reward_base(user_id):
    reset_daily_contracts_if_needed(user_id)

    active_contract = get_active_contract(user_id)

    if not active_contract:
        return {
            "success": False,
            "message": "📜 У тебе немає контракту для здачі."
        }

    if not active_contract.get("completed"):
        return {
            "success": False,
            "message": (
                "❌ Контракт ще не виконано.\n\n"
                f"🎯 Ціль: {active_contract['target_mob_name']}\n"
                f"📈 Прогрес: {active_contract['current_kills']}/{active_contract['target_kills']}"
            )
        }

    if active_contract.get("reward_claimed"):
        return {
            "success": False,
            "message": "✅ Нагороду за цей контракт уже отримано."
        }

    reward_exp = active_contract["reward_exp"]

    exp_result = add_exp(user_id, reward_exp)

    cursor.execute("""
    UPDATE users
    SET daily_contracts_completed = daily_contracts_completed + 1
    WHERE user_id=?
    """, (user_id,))

    cursor.execute("""
    UPDATE user_active_contracts
    SET reward_claimed=1
    WHERE id=?
    """, (active_contract["id"],))

    cursor.execute("""
    DELETE FROM user_active_contracts
    WHERE id=?
    """, (active_contract["id"],))

    conn.commit()

    message = (
        f"🎁 Контракт здано!\n\n"
        f"🎯 Ціль: {active_contract['target_mob_name']}\n"
        f"✨ Нагорода: +{reward_exp} EXP"
    )

    if exp_result and exp_result.get("level_ups", 0) > 0:
        message += f"\n🏆 Новий рівень: {exp_result['level']}!"

    return {
        "success": True,
        "message": message,
        "reward_exp": reward_exp,
        "exp_result": exp_result
    }


def _contract_result_success(result):
    if not isinstance(result, dict):
        return False
    if result.get("success") is True:
        return True
    return "контракт здано" in str(result.get("message") or "").lower()

def claim_contract_reward(user_id):
    contract = get_active_contract(user_id)
    result = _claim_contract_reward_base(user_id)
    if not _contract_result_success(result):
        return result
    try:
        guild_result = _db.award_guild_contract_completion(user_id=user_id, contract=contract or "контракт")
        guild_text = _db.get_guild_activity_reward_text(guild_result)
        if guild_text and isinstance(result, dict):
            message = str(result.get("message") or "")
            if guild_text not in message:
                result["message"] = (message.rstrip() + "\n\n" + guild_text).strip()
    except Exception as error:
        print(f"WARNING: Guild contract reward failed: {error}")
    return result

def get_daily_contract_reset_info(user_id=None):
    today = get_today_str()
    if user_id is None:
        return {"today": today}
    row = cursor.execute("SELECT daily_contract_date, daily_contracts_completed FROM users WHERE user_id=?", (user_id,)).fetchone()
    if not row:
        return {"today": today, "date": "", "completed": 0}
    return {"today": today, "date": row[0] or "", "completed": int(row[1] or 0)}

def migrate_contract_target_kills_to_v2(*args, **kwargs):
    return migrate_active_contracts_target_kills_to_5()
